            SAXParserFactory factory = SAXParserFactory.newInstance();
            factory.setNamespaceAware(true);

            // Disable DOCTYPE declarations to prevent XXE attacks
            try {
                factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            } catch (Exception e) {
                // Fallback: disable external entities individually
                factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
                factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
                factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            }

            // Enable secure processing to limit entity expansion and other risky operations
            factory.setFeature(javax.xml.XMLConstants.FEATURE_SECURE_PROCESSING, true);

            // Step 2: Obtain a SAX parser and its XMLReader
            SAXParser saxParser = factory.newSAXParser();
            XMLReader xmlReader = saxParser.getXMLReader();

            // Step 3: Prepare SAXSource with the XMLReader and the file input
            InputSource inputSource = new InputSource(inputStream);
            SAXSource source = new SAXSource(xmlReader, inputSource);

            // Step 4: Use an identity transformer to convert SAX events into a DOM Document
            TransformerFactory transformerFactory = TransformerFactory.newInstance();
            Transformer transformer = transformerFactory.newTransformer();
            DOMResult domResult = new DOMResult();
            transformer.transform(source, domResult);

            // Step 5: Extract and return the Document
            Document document = (Document) domResult.getNode();
            if (document == null) {
                throw new ConfigurationException("Failed to parse XML document: result is null");
            }
            return document;

        } catch (IOException e) {
            throw new ConfigurationException("Failed to read configuration file: " + configPath, e);
        } catch (SAXException | javax.xml.parsers.ParserConfigurationException | TransformerException e) {
            throw new ConfigurationException("Failed to parse XML configuration: " + e.getMessage(), e);
        }
    }

    /**
     * Custom runtime exception for configuration loading errors.
     * This avoids forcing callers to catch checked exceptions in common utility methods.
     */
    public static class ConfigurationException extends RuntimeException {
        public ConfigurationException(String message) {
            super(message);
        }

        public ConfigurationException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
